import { Component, OnInit, OnDestroy } from '@angular/core';
import { Subscription } from 'rxjs';
import { DoctorService } from '../../../core/services/doctor.service';
import { AuthService } from '../../../core/services/auth.service';
import { WebSocketService } from '../../../core/services/websocket.service';
import { Token, TokenStatus } from '../../../core/models';

@Component({
  selector: 'app-doctor-queue',
  templateUrl: './doctor-queue.component.html'
})
export class DoctorQueueComponent implements OnInit, OnDestroy {

  queue: Token[] = [];
  currentToken: Token | null = null;
  loading = false;
  actionLoading = false;
  error = '';
  success = '';

  private wsSub: Subscription | null = null;

  constructor(
    private doctorService: DoctorService,
    private auth: AuthService,
    private ws: WebSocketService
  ) {}

  ngOnInit(): void {
    this.loadQueue();
  }

  loadQueue(): void {
    this.loading = true;
    this.doctorService.getMyQueue().subscribe({
      next: tokens => {
        this.processQueue(tokens);
        this.loading = false;
        this.subscribeToRealTimeUpdates();
      },
      error: () => { this.loading = false; }
    });
  }

  callNext(): void {
    this.actionLoading = true;
    this.error = '';
    this.doctorService.callNextPatient().subscribe({
      next: token => {
        this.success = `Now serving: ${token.patientName} (${token.tokenNumber})`;
        this.loadQueue();
        this.actionLoading = false;
        setTimeout(() => this.success = '', 4000);
      },
      error: err => {
        this.error = err.error?.message ?? 'No patients in queue.';
        this.actionLoading = false;
      }
    });
  }

  completeCurrentToken(): void {
    if (!this.currentToken) return;
    this.actionLoading = true;

    this.doctorService.updateTokenStatus(this.currentToken.id, { status: 'COMPLETED' as TokenStatus }).subscribe({
      next: () => {
        this.success = 'Consultation completed.';
        this.currentToken = null;
        this.loadQueue();
        this.actionLoading = false;
        setTimeout(() => this.success = '', 4000);
      },
      error: err => {
        this.error = err.error?.message ?? 'Failed to complete.';
        this.actionLoading = false;
      }
    });
  }

  getPriorityClass(p: string): string {
    return `badge badge-${p.toLowerCase()}`;
  }

  private processQueue(tokens: Token[]): void {
    this.currentToken = tokens.find(t => t.status === 'IN_PROGRESS') ?? null;
    this.queue = tokens.filter(t => t.status === 'WAITING');
  }

  private subscribeToRealTimeUpdates(): void {
    const user = this.auth.getCurrentUser();
    if (!user) return;

    // Use doctorId from the first token if available, or fall back to userId
    const doctorId = this.currentToken?.doctorId ?? this.queue[0]?.doctorId;
    if (!doctorId) return;

    this.wsSub?.unsubscribe();
    this.wsSub = this.ws.subscribeToQueue<Token[]>(doctorId).subscribe(updated => {
      this.processQueue(updated);
    });
  }

  ngOnDestroy(): void {
    this.wsSub?.unsubscribe();
  }
}
<div class="page-header">
  <h2>My Queue</h2>
  <p>Manage your patient consultation queue in real time</p>
</div>

<div *ngIf="success" class="alert alert-success">{{ success }}</div>
<div *ngIf="error"   class="alert alert-danger">{{ error }}</div>

<!-- Current Patient -->
<div class="card" style="border-left: 4px solid #007bff;">
  <h4 style="margin-bottom:16px; color:#1a3c5e;">Current Patient</h4>

  <div *ngIf="currentToken; else noCurrentPatient">
    <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:16px;">
      <div>
        <div class="token-number">{{ currentToken.tokenNumber }}</div>
        <p style="font-size:18px; font-weight:600; margin-top:8px;">{{ currentToken.patientName }}</p>
        <p style="color:#6c757d;">{{ currentToken.patientPhone }}</p>
        <span [class]="getPriorityClass(currentToken.priority)" style="margin-top:8px; display:inline-block;">
          {{ currentToken.priority }}
        </span>
      </div>
      <div style="display:flex; gap:12px;">
        <button class="btn btn-success" (click)="callNext()" [disabled]="actionLoading">
          Call Next
        </button>
        <button class="btn btn-secondary" (click)="completeCurrentToken()" [disabled]="actionLoading">
          Complete &amp; Done
        </button>
      </div>
    </div>
  </div>

  <ng-template #noCurrentPatient>
    <p style="color:#6c757d; margin-bottom:16px;">No patient is currently in consultation.</p>
    <button class="btn btn-primary" (click)="callNext()" [disabled]="actionLoading || queue.length === 0">
      {{ actionLoading ? 'Loading...' : 'Call First Patient' }}
    </button>
  </ng-template>
</div>

<!-- Waiting Queue -->
<div class="card">
  <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:16px;">
    <h4 style="color:#1a3c5e;">Waiting Queue ({{ queue.length }})</h4>
    <button class="btn btn-secondary" (click)="loadQueue()" [disabled]="loading" style="font-size:13px;">
      Refresh
    </button>
  </div>

  <table *ngIf="queue.length > 0">
    <thead>
      <tr>
        <th>Position</th>
        <th>Token #</th>
        <th>Patient</th>
        <th>Priority</th>
        <th>Arrived At</th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let token of queue; let i = index"
          [style.background]="token.priority === 'EMERGENCY' ? '#fff5f5' : token.priority === 'URGENT' ? '#fffbf0' : ''">
        <td>
          <span class="queue-position" style="font-size:20px;">{{ i + 1 }}</span>
        </td>
        <td><strong>{{ token.tokenNumber }}</strong></td>
        <td>
          {{ token.patientName }}<br>
          <small style="color:#6c757d;">{{ token.patientPhone }}</small>
        </td>
        <td><span [class]="getPriorityClass(token.priority)">{{ token.priority }}</span></td>
        <td style="font-size:13px; color:#6c757d;">
          {{ token.createdAt | date:'HH:mm' }}
        </td>
      </tr>
    </tbody>
  </table>

  <p *ngIf="!loading && queue.length === 0"
     style="text-align:center; color:#6c757d; padding:24px;">
    No patients waiting in the queue.
  </p>
</div>
